import{_ as t,C as n,o as s,c as i,j as r,a as l,G as o,a2 as c}from"./chunks/framework.BgSoyxN5.js";const P=JSON.parse('{"title":"TickerForge Partner Cabinet | Как одобренные партнёры создают посты в Telegram","description":"Как устроен Partner Cabinet TickerForge: кто получает доступ, какие партнёрские посты там создаются, как работают отслеживаемые ссылки и статистика, чем «сгенерирован» отличается от «опубликован».","frontmatter":{"title":"TickerForge Partner Cabinet | Как одобренные партнёры создают посты в Telegram","description":"Как устроен Partner Cabinet TickerForge: кто получает доступ, какие партнёрские посты там создаются, как работают отслеживаемые ссылки и статистика, чем «сгенерирован» отличается от «опубликован».","aside":false,"locale":"ru","alternateLocales":{"en":"/partners/cabinet","ru":"/ru/partners/cabinet"},"pageClass":"partners-page"},"headers":[],"relativePath":"ru/partners/cabinet.md","filePath":"ru/partners/cabinet.md","lastUpdated":1788362384000}'),p={name:"ru/partners/cabinet.md"};function d(h,a,u,g,m,f){const e=n("PartnerPageAnalytics");return s(),i("div",null,[a[0]||(a[0]=r("h1",{id:"как-работает-partner-cabinet",tabindex:"-1"},[l("Как работает Partner Cabinet "),r("a",{class:"header-anchor",href:"#как-работает-partner-cabinet","aria-label":'Permalink to "Как работает Partner Cabinet"'},"​")],-1)),a[1]||(a[1]=r("p",null,"Partner Cabinet — это место, где одобренный партнёр реально создаёт партнёрские посты. Он живёт внутри Telegram, а не на сайте.",-1)),o(e,{offer:"cabinet",locale:"ru"}),a[2]||(a[2]=c('<p class="partners-locale-switch"><a href="/partners/cabinet" hreflang="en" data-partner-event="cta" data-partner-option="locale_en" data-analytics-placement="partner_locale_switch">Read this page in English</a></p><p class="partners-backlink"><a href="/ru/partners">Все варианты партнёрства</a> · <a href="/ru/partners/stock-analysis-and-ideas">Исследования в Telegram</a> · <a href="/ru/partners/market-news">Рыночные новости</a> · <a href="/ru/partners/portfolio-health">Здоровье портфеля</a> · <a href="/ru/partners/requirements">Требования к партнёрам</a></p><h2 id="как-попасть-внутрь" tabindex="-1">Как попасть внутрь <a class="header-anchor" href="#как-попасть-внутрь" aria-label="Permalink to &quot;Как попасть внутрь&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Сначала одобрение.</strong> Отправленная форма создаёт заявку. Ничего не выдаётся, пока её не посмотрит человек — см. <a href="/ru/partners/requirements#lifecycle">жизненный цикл статуса</a>.</li><li><strong>Откройте <code>/partners</code> в Telegram.</strong> Одна и та же команда показывает публичный раздел программы всем и Partner Cabinet — одобренным партнёрам.</li><li><strong>Доступ привязан к вашему аккаунту Telegram.</strong> Кабинет открывает именно одобренный аккаунт. Партнёрский код, введённый кем-то другим, не даёт ничего, и доступ не передаётся.</li><li><strong>Доступ ограничен по времени.</strong> Когда окно пилота заканчивается или ставится на паузу, кабинет закрывается и посты больше не генерируются.</li></ul></div><h2 id="как-создается-партнерскии-пост" tabindex="-1">Как создаётся партнёрский пост <a class="header-anchor" href="#как-создается-партнерскии-пост" aria-label="Permalink to &quot;Как создаётся партнёрский пост&quot;">​</a></h2><p>Одобренный партнёр создаёт поддерживаемые партнёрские посты в Telegram Partner Cabinet. Слово «поддерживаемые» здесь важно: кабинет генерирует те форматы, за которыми уже стоит рабочий генератор, а остальные форматы со страниц направлений готовятся вместе с нами в рамках пилота.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Посты по компании.</strong> Вводите тикер и получаете готовый пост: вердикт по акции, активность инсайдеров, движения фондов.</li><li><strong>Посты-идеи.</strong> «Разворот» и «Инсайдеры покупают» умеют брать текущую подходящую идею или проверить введённый вами тикер по тому же правилу, что и пост в канале.</li><li><strong>Рыночный пост.</strong> Рыночный апдейт на основе текущего недельного обзора рыночного режима. Тикер не нужен.</li><li><strong>Всё остальное со страниц направлений</strong> запрашивается: напишите в форме, какой формат важен, и спрос партнёров определит, что станет self-serve следующим.</li></ul></div><h2 id="отслеживаемые-ссылки" tabindex="-1">Отслеживаемые ссылки <a class="header-anchor" href="#отслеживаемые-ссылки" aria-label="Permalink to &quot;Отслеживаемые ссылки&quot;">​</a></h2><p>У каждого сгенерированного поста своя отслеживаемая ссылка. Публичная ссылка короткая и непрозрачная — в ней не зашиты код партнёра, месяц, рубрика, workflow или тикер. Всё это остаётся внутри TickerForge как поля отчёта.</p><p>Читатель по ссылке попадает в соответствующий сценарий TickerForge, а привязку определяют действующие реферальные правила. Работает первое касание: читателя, который уже закреплён за другим амбассадором, не переприсваивают.</p><h2 id="статистика-и-отчеты" tabindex="-1">Статистика и отчёты <a class="header-anchor" href="#статистика-и-отчеты" aria-label="Permalink to &quot;Статистика и отчёты&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Статистика:</strong> отслеживаемые клики, рефералы, платные рефералы текущего месяца и короткая разбивка по типам постов.</li><li><strong>Месячный отчёт:</strong> текущий или предыдущий месяц в XLSX с листами Summary и Posts.</li><li><strong>Raw clicks</strong> — это переходы по ссылке, а не уникальные люди.</li><li><strong>Bot starts</strong> — уникальные пользователи Telegram, чей первый партнёрский старт пришёл из конкретного поста.</li><li><strong>Платные подписки</strong> — текущий снимок активных платных планов среди ваших рефералов, а не история платежей.</li></ul></div><h2 id="сгенерирован-—-не-значит-опубликован" tabindex="-1">Сгенерирован — не значит опубликован <a class="header-anchor" href="#сгенерирован-—-не-значит-опубликован" aria-label="Permalink to &quot;Сгенерирован — не значит опубликован&quot;">​</a></h2><div class="partners-wide partners-routing-note"><p><strong>Генерация поста в кабинете не считается публикацией.</strong> Кабинет отдельно показывает сгенерированные и подтверждённые посты, и в обязательства по пилоту засчитываются только опубликованные посты, которые мы можем проверить.</p><a class="partners-button partners-button--secondary" href="/ru/partners/requirements#commitments">Посмотреть обязательства по публикациям</a></div><h2 id="чем-кабинет-не-является" tabindex="-1">Чем кабинет не является <a class="header-anchor" href="#чем-кабинет-не-является" aria-label="Permalink to &quot;Чем кабинет не является&quot;">​</a></h2><div class="partners-wide partners-wide--not"><p>Partner Cabinet не:</p><ul><li>публикует посты в ваш канал за вас</li><li>выдаёт доступ тому, кому вы переслали ссылку</li><li>генерирует каждый формат, перечисленный на страницах направлений</li><li>заменяет ваш собственный анализ, дисклеймер и редакторское решение</li></ul></div><h2 id="смотрите-также" tabindex="-1">Смотрите также <a class="header-anchor" href="#смотрите-также" aria-label="Permalink to &quot;Смотрите также&quot;">​</a></h2><ul><li><a href="/ru/partners">Все варианты партнёрства</a></li><li><a href="/ru/partners/requirements">Требования к партнёрам</a></li><li><a href="/ru/partners/stock-analysis-and-ideas">Исследования в Telegram</a></li><li><a href="/ru/partners/market-news">Рыночные новости</a></li><li><a href="/ru/partners/portfolio-health">Здоровье портфеля</a></li><li><a href="/ambassador">Реферальная программа Ambassador</a></li></ul>',18))])}const k=t(p,[["render",d]]);export{P as __pageData,k as default};
